Here is the commit message:
nfsd: fix nfs4_file refcount leak in nfsd_get_dir_deleg()

Claude pointed out that there is a nfs4_file refcount leak in
nfsd_get_dir_deleg(). Ensure that the reference to "fp" is released
before returning.

Fixes: 8b99f6a8c116 ("nfsd: wire up GET_DIR_DELEGATION handling")
Cc: stable@vger.kernel.org
Cc: Chris Mason <clm@meta.com>
Signed-off-by: Jeff Layton <jlayton@kernel.org>
Signed-off-by: Chuck Lever <chuck.lever@oracle.com>

Here is the root cause:
In `nfsd_get_dir_deleg()`, a reference to the `nfs4_file` (fp) is obtained but not released in all code paths. When the delegation is successfully granted (status == 0), the function returns `dp` without calling `put_nfs4_file(fp)`, causing a leak. Additionally, in the error path, the cleanup releases the lease, puts the stid, and calls `put_deleg_file(fp)`, but still fails to release the original fp reference via `put_nfs4_file(fp)`.

Here is the patch:
  */
 struct nfs4_delegation *
 nfsd_get_dir_deleg(struct nfsd4_compound_state *cstate,
 		   struct nfsd4_get_dir_delegation *gdd,
 		   struct nfsd_file *nf)
 {
 	struct nfs4_client *clp = cstate->clp;
 	struct nfs4_delegation *dp;
 	struct file_lease *fl;
 	struct nfs4_file *fp, *rfp;
 	int status = 0;

 	fp = nfsd4_alloc_file();
 	if (!fp)
 		return ERR_PTR(-ENOMEM);

 	nfsd4_file_init(&cstate->current_fh, fp);

 	rfp = nfsd4_file_hash_insert(fp, &cstate->current_fh);
 	if (unlikely(!rfp)) {
 		put_nfs4_file(fp);
 		return ERR_PTR(-ENOMEM);
 	}

 	if (rfp != fp) {
 		put_nfs4_file(fp);
 		fp = rfp;
 	}

 	/* if this client already has one, return that it's unavailable */
 	spin_lock(&state_lock);
 	spin_lock(&fp->fi_lock);
 	/* existing delegation? */
 	if (nfs4_delegation_exists(clp, fp)) {
 		status = -EAGAIN;
 	} else if (!fp->fi_deleg_file) {
 		fp->fi_deleg_file = nfsd_file_get(nf);
 		fp->fi_delegees = 1;
 	} else {
 		++fp->fi_delegees;
 	}
 	spin_unlock(&fp->fi_lock);
 	spin_unlock(&state_lock);

 	if (status) {
 		put_nfs4_file(fp);
 		return ERR_PTR(status);
 	}

 	/* Try to set up the lease */
 	status = -ENOMEM;
 	dp = alloc_init_deleg(clp, fp, NULL, NFS4_OPEN_DELEGATE_READ);
 	if (!dp)
 		goto out_delegees;

 	fl = nfs4_alloc_init_lease(dp);
 	if (!fl)
 		goto out_put_stid;

 	status = kernel_setlease(nf->nf_file,
 				 fl->c.flc_type, &fl, NULL);
 	if (fl)
 		locks_free_lease(fl);
 	if (status)
 		goto out_put_stid;

 	/*
 	 * Now, try to hash it. This can fail if we race another nfsd task
 	 * trying to set a delegation on the same file. If that happens,
 	 * then just say UNAVAIL.
 	 */
 	spin_lock(&state_lock);
 	spin_lock(&clp->cl_lock);
 	spin_lock(&fp->fi_lock);
 	status = hash_delegation_locked(dp, fp);
 	spin_unlock(&fp->fi_lock);
 	spin_unlock(&clp->cl_lock);
 	spin_unlock(&state_lock);

-	if (!status)
+	if (!status) {
+		put_nfs4_file(fp);
 		return dp;
+	}

 	/* Something failed. Drop the lease and clean up the stid */
 	kernel_setlease(fp->fi_deleg_file->nf_file, F_UNLCK, NULL, (void **)&dp);
 out_put_stid:
 	nfs4_put_stid(&dp->dl_stid);
 out_delegees:
 	put_deleg_file(fp);
+	put_nfs4_file(fp);
 	return ERR_PTR(status);
 }
-- 


